style.css:
@-moz-document regexp(".*") {
/* Background and global text settings */
    html, body, div, p, span, section, main, header, footer, aside, article {
        background-color: #A05D6E !important; /* Dark Pastel Pink */
        color: #000000 !important;           /* Black Text */
    }

    /* Text shadow for all standard text elements */
    body, p, span, h1, h2, h3, h4, h5, h6, li, td, th {
        text-shadow: 1px 1px 2px #F4C2C2 !important; /* Baby Pink Shadow */
        color: #000000 !important;
    }

    /* Neon Pink Links */
    a, a *, .link, [role="link"] {
        color: #FF1493 !important;           /* Neon Pink */
        text-decoration: underline !important;
        text-shadow: none !important;        /* Clearer link readability */
    }

    /* Hover effect for links */
    a:hover, a:hover * {
        color: #FF69B4 !important;           /* Brighter Neon on hover */
    }

    /* Force input fields to remain readable */
    input, textarea, select {
        background-color: #F4C2C2 !important; /* Lighter pink for input areas */
        color: #000000 !important;
    }
}
